</head>
<body>
<div id="app"></div>
<div id="title">
  <h1>神奈川沖浪裏</h1>
  <p>The Great Wave off Kanagawa · after Katsushika Hokusai (public domain)</p>
</div>
<script type="module">
import * as THREE from "https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js";

/* ---------- palette sampled from the print ---------- */
const C = {
  skyTop:   0xf3ead2,  // warm paper cream
  skyBot:   0xe4d6b4,
  deep:     0x16324f,  // darkest indigo
  mid:      0x1f4e79,  // mid indigo
  light:    0x5b8cae,  // pale blue
  foam:     0xf2efe4,  // white foam
  paper:    0xe8ddc4,
  hull:     0xc98d5a,  // tan hull
  hullDark: 0x8a5a33,
  fuji:     0x2b4a6b,  // Fuji blue
  fujiSnow: 0xf4f1e8,
  ink:      0x101820,
};

/* ---------- renderer / scene / camera ---------- */
const app = document.getElementById("app");
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.setSize(innerWidth, innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
app.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.background = new THREE.Color(C.skyTop);
scene.fog = new THREE.Fog(C.skyBot, 60, 160);

const camera = new THREE.PerspectiveCamera(42, innerWidth / innerHeight, 0.1, 400);
camera.position.set(0, 7, 46);
camera.lookAt(0, 4, 0);

/* ---------- lights ---------- */
scene.add(new THREE.HemisphereLight(C.skyTop, C.mid, 1.1));
const sun = new THREE.DirectionalLight(0xfff2d8, 1.2);
sun.position.set(-20, 30, 20);
scene.add(sun);

/* ---------- sky gradient plane (paper) ---------- */
{
  const g = new THREE.BufferGeometry();
  const pos = new Float32Array([-100, -20, -80, 100, -20, -80, 100, 60, -80, -100, 60, -80]);
  const top = new THREE.Color(C.skyTop), bot = new THREE.Color(C.skyBot);
  const col = new Float32Array([
    bot.r, bot.g, bot.b,
    bot.r, bot.g, bot.b,
    top.r, top.g, top.b,
    top.r, top.g, top.b,
  ]);
  g.setAttribute("position", new THREE.BufferAttribute(pos, 3));
  g.setAttribute("color", new THREE.BufferAttribute(col, 3));
  const m = new THREE.MeshBasicMaterial({ vertexColors: true, side: THREE.DoubleSide });
  scene.add(new THREE.Mesh(g, m));
}

/* ---------- helpers ---------- */
function mat(color, flat = true) {
  return new THREE.MeshStandardMaterial({ color, flatShading: flat, roughness: .9, metalness: 0 });
}
function coneGeo(r, h, seg) { return new THREE.ConeGeometry(r, h, seg); }

/* ---------- Mt. Fuji: flat blue cone + snow cap ---------- */
const fuji = new THREE.Group();
{
  const body = new THREE.Mesh(coneGeo(16, 18, 5), mat(C.fuji));
  body.position.y = 9;
  fuji.add(body);
  // snow cap: shorter lighter cone on top, slightly smaller
  const cap = new THREE.Mesh(coneGeo(6.2, 7, 5), mat(C.fujiSnow));
  cap.position.y = 18 - 3.5 + 1.2;
  fuji.add(cap);
  // jagged snow edge: ring of small white cones
  for (let i = 0; i < 5; i++) {
    const a = (i / 5) * Math.PI * 2 + 0.4;
    const s = new THREE.Mesh(coneGeo(1.6, 2.4, 4), mat(C.fujiSnow));
    s.position.set(Math.cos(a) * 5.6, 15.6, Math.sin(a) * 5.6);

